before:
Complete local Kotlin/JVM example; the app itself does not execute it:
```kotlin
import kotlinx.coroutines.runBlocking
import kotlinx.coroutines.coroutineScope
import kotlinx.coroutines.async

fun main() {
    runBlocking {
        val total = coroutineScope {
            val left = async { 6 }
            val right = async { 7 }
            left.await() + right.await()
        }
        println(total)
    }
}
```

